def topological_sort(graph):
    visited = set()
    order = []
    # States: 0 = unvisited, 1 = visiting (in current path), 2 = visited (complete)
    state = {}

    def visit(node):
        if state.get(node) == 1:
            raise ValueError('cycle detected')
        if state.get(node) == 2:
            return
        state[node] = 1  # Mark as visiting
        for dependency in graph.get(node, []):
            visit(dependency)
        state[node] = 2  # Mark as visited
        order.append(node)

    for node in graph:
        visit(node)
    return order
```

