def parse_csv_line(line):
    fields = []
    current_field = []
    in_quotes = False
    i = 0
    while i < len(line):
        char = line[i]
        if in_quotes:
            if char == '"':
                # Check for escaped quote
                if i + 1 < len(line) and line[i + 1] == '"':
                    current_field.append('"')
                    i += 2
                else:
                    # End of quoted field
                    in_quotes = False
                    i += 1
            else:
                current_field.append(char)
                i += 1
        else:
            if char == '"':
                # Start of quoted field
                in_quotes = True
                i += 1
            elif char == ',':
                fields.append(''.join(current_field))
                current_field = []
                i += 1
            else:
                current_field.append(char)
                i += 1
    fields.append(''.join(current_field))
    return fields
