import json
import os
import tempfile
import config_store


def test_load_existing_json():
    """Test loading an existing JSON file."""
    with tempfile.NamedTemporaryFile(mode='w', suffix='.json', delete=False) as f:
        json.dump({"key": "value"}, f)
        temp_path = f.name
    try:
        result = config_store.load_or_create(temp_path, {"fallback": True})
        assert result == {"key": "value"}
    finally:
        os.unlink(temp_path)


def test_create_missing_file():
    """Test creating a missing JSON file with default content."""
    temp_path = tempfile.mktemp_file(suffix='.json')
    try:
        result = config_store.load_or_create(temp_path, {"key": "value"})
        assert result == {"key": "value"}
        with open(temp_path, 'r', encoding='utf-8') as f:
            assert json.load(f) == {"key": "value"}
    finally:
        os.unlink(temp_path)


def test_create_nested_directories():
    """Test creating parent directories when they don't exist."""
    temp_dir = tempfile.mkdtemp_dir()
    nested_path = os.path.join(temp_dir, "subdir", "nested.json")
    try:
        result = config_store.load_or_create(nested_path, {"nested": "value"})
        assert result == {"nested": "value"}
        assert os.path.exists(nested_path)
        with open(nested_path, 'r', encoding='utf-8') as f:
            assert json.load(f) == {"nested": "value"}
    finally:
        os.rmtree(temp_dir)


def test_load_non_json_file():
    """Test loading a non-JSON file should raise an error or handle gracefully."""
    temp_path = tempfile.mktemp_file(suffix='.txt')
    try:
        with open(temp_path, 'w') as f:
            f.write("not json")
        try:
            config_store.load_or_create(temp_path, "default")
            assert False, "Expected an exception"
        except Exception:
            pass  # Expected behavior
    finally:
