    @patch('process_runner.subprocess.run')
    def test_success_returns_trimmed_stdout(self, mock_run):
        """Test that successful command returns trimmed stdout."""
        mock_run.return_value = MagicMock(returncode=0, stdout='  hello world  \n')
        result = run_checked(['echo', 'hello', 'world'])
