    def test_failure_raises_runtime_error_with_stderr(self, mock_run):
        """Test that failed command raises RuntimeError with stderr."""
        mock_run.return_value = MagicMock(returncode=1, stderr='error occurred')
        with self.assertRaises(RuntimeError) as context:
            run_checked(['some', 'command'])
        self.assertIn('error occurred', str(context.exception))

    @patch('process_runner.subprocess.run')
    def test_no_shell_used(self, mock_run):
        """Test that subprocess.run is called without shell=True."""
        run_checked(['echo', 'test'])
        # Check that shell was not used (default is False)
        mock_run.assert_called_once()
        call_kwargs = mock_run.call_args
        # Ensure shell is not set to True
        if 'shell' in call_kwargs:
            self.assertFalse(call_kwargs['shell'])

    @patch('process_runner.subprocess.run')
    def test_empty_stdout_on_success(self, mock_run):
        """Test that empty stdout is handled correctly."""
        mock_run.return_value = MagicMock(returncode=0, stdout='')
        result = run_checked(['echo', '-n'])
        self.assertEqual(result, '')

    @patch('process_runner.subprocess.run')
    def test_multiline_stdout_is_trimmed(self, mock_run):
        """Test that multiline stdout is trimmed."""
        mock_run.return_value = MagicMock(returncode=0, stdout='  line1\nline2  \n')
        result = run_checked(['cat'])
        self.assertEqual(result, 'line1\nline2')

    @patch('process_runner.subprocess.run')
    def test_stderr_only_on_failure(self, mock_run):
        """Test that only stderr is included in error message."""
        mock_run.return_value = MagicMock(returncode=1, stderr='only stderr')
        with self.assertRaises(RuntimeError) as context:
            run_checked(['command'])
        self.assertEqual(str(context.exception), 'only stderr')

    @patch('process_runner.subprocess.run')
    def test_argv_passed_correctly(self, mock_run):
        """Test that argv is passed correctly to subprocess.run."""
