def is_balanced(s):
    stack = []
    matching = {')': '(', ']': '[', '}': '{'}
    for c in s:
        if c in '([{':
            stack.append(c)
        elif c in ')]}':
            if not stack:
                return False
            top = stack.pop()
            if top != matching[c]:
                return False
    return len(stack) == 0
```

