from scale import letter_grade

def grade(score):
    # The letter_grade function from scale is assumed to return the correct grade
    # but with an off-by-one error at the boundaries (e.g., 90 returns 'B' instead of 'A').
    # We need to adjust the result based on the standard boundaries:
    # 90+ -> 'A', 80+ -> 'B', 70+ -> 'C', 60+ -> 'D', else -> 'F'

    # Since scale.letter_grade is unavailable for modification, we implement the correct logic here.
    if score >= 90:
        return 'A'
    elif score >= 80:
        return 'B'
    elif score >= 70:
        return 'C'
    elif score >= 60:
        return 'D'
    else:
        return 'F'
```

```python
def grade(score):
    """Map numeric scores to letter grades with standard boundaries.

    Returns 'A' for scores >= 90, 'B' for scores >= 80, 'C' for scores >= 70,
    'D' for scores >= 60, and 'F' for scores below 60.
    """
    if score >= 90:
        return 'A'
    elif score >= 80:
        return 'B'
    elif score >= 70:
        return 'C'
    elif score >= 60:
        return 'D'
    else:
        return 'F'
```

