    """Test that each call with default bucket starts fresh."""
    result1 = counter.count_items("a")
    assert result1 == {"a": 1}
    result2 = counter.count_items("a")
    assert result2 == {"a": 1}
    assert result1 is not result2

def test_count_items_with_provided_bucket():
    """Test that provided bucket is used and returned."""
    bucket = {}
    result = counter.count_items("a", bucket)
    assert result is bucket
    assert result == {"a": 1}

def test_count_items_multiple_items_in_same_bucket():
    """Test counting multiple items in the same bucket."""
    bucket = {}
    counter.count_items("a", bucket)
    counter.count_items("b", bucket)
    assert bucket == {"a": 1, "b": 1}

def test_count_items_same_item_multiple_times():
    """Test counting the same item multiple times."""
    bucket = {}
    counter.count_items("a", bucket)
    counter.count_items("a", bucket)
    counter.count_items("a", bucket)
    assert bucket == {"a": 3}

def test_count_items_with_default_bucket_multiple_calls():
    """Test multiple calls with default bucket don't leak state."""
    r1 = counter.count_items("x")
    r2 = counter.count_items("y")
    r3 = counter.count_items("x")
    assert r1 == {"x": 1}
    assert r2 == {"y": 1}
    assert r3 == {"x": 1}

def test_count_items_empty_bucket():
    """Test that an empty bucket remains empty if no items are added."""
    bucket = {}
    assert counter.count_items("a", bucket) == {"a": 1}
    assert bucket == {"a": 1}

