def parse_bool(value):
    """Parse a boolean value from various input types.

    Args:
        value: The value to parse. Can be bool, int, or str.

    Returns:
        A boolean representation of the input value.

    Raises:
        ValueError: If the input is a string that doesn't match any known truthy/falsy values.
    """
    if isinstance(value, bool):
        return value
    elif isinstance(value, int):
        return bool(value)
    elif isinstance(value, str):
        value_lower = value.lower()
        if value_lower in ('true', 'yes', '1'):
            return True
        elif value_lower in ('false', 'no', '0'):
