def parse_bool(value):
    """
    Parse a boolean value from various input types.

    Accepts bool, int, and str.
    True/1/'true'/'yes'/'1' (case-insensitive) are True;
    False/0/'false'/'no'/'0' are False.
    Other strings raise ValueError.
    """
    if isinstance(value, bool):
        return value
    elif isinstance(value, int):
        # Note: bool is a subclass of int, so we need to check bool first
        return bool(value)
    elif isinstance(value, str):
        lower_value = value.lower()
        if lower_value in ('true', 'yes', '1'):
            return True
        elif lower_value in ('false', 'no', '0'):
            return False
        else:
            raise ValueError(f"Invalid boolean string: '{value}'")
    else:
        raise ValueError(f"Unsupported type for boolean conversion: {type(value)}")
```

