# Try to import the helper from lib.pathutil if available, otherwise define a fallback
try:
    from lib.pathutil import collapse_slashes
except ImportError:
    def collapse_slashes(path):
        """Fallback implementation of collapse_slashes."""
        # Collapse multiple '/' into single '/' while preserving leading '/' if present
        if path.startswith('/'):
            return '/' + '/'.join(p for p in path.split('/')[1:] if p != '')
        return '/'.join(p for p in path.split('/') if p != '')

def clean_path(path):
    """
    Clean a path by collapsing repeated '/' characters while preserving
    whether the path is absolute.

    Args:
        path (str): The path to clean.

    Returns:
        str: The cleaned path.
    """
    # Use the helper from lib.pathutil (or the fallback)
    return collapse_slashes(path)
